def brackets_balanced(s: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())
    closers = set(pairs.keys())

    i = 0
    n = len(s)
    in_string = False

    while i < n:
        c = s[i]
        if in_string:
            if c == '\\':
                # escaped char, skip next character too
                i += 2
                continue
            elif c == '"':
                in_string = False
                i += 1
                continue
            else:
                i += 1
                continue
        else:
            if c == '"':
                in_string = True
                i += 1
                continue
            elif c in openers:
                stack.append(c)
                i += 1
                continue
            elif c in closers:
                if not stack or stack[-1] != pairs[c]:
                    return False
                stack.pop()
                i += 1
                continue
            else:
                i += 1
                continue

    if in_string:
        return False

    return len(stack) == 0
